package ics.recents;

import android.content.res.Resources;
import android.graphics.drawable.Drawable;

/** TechnoUI holo toast/dialog artwork (mdpi 9-patches), registered into VolArt's loader. */
public class HoloArt {
    /** Bitmap density the art is drawn at. 160 = original mdpi size (thin on a 480dpi phone), 240 = 1.5x, 320 = 2x. */
    static final int DPI = 240;
    static boolean ready;

    static synchronized void init() {
        if (ready) return;
        ready = true;
        VolArt.put("toast", DPI, "");
        VolArt.put("dialog_full", DPI, "");
        VolArt.put("dialog_div", DPI, "iVBORw0KGgoAAAANSUhEUgAAAAsAAAAGCAYAAAAVMmT4AAAAAXNSR0IArs4c6QAAAARzQklUCAgICHwIZIgAAABESURBVBiVY2DADv5jE2SC0i0MDAxvoYr+I2n4DxVvQdb09sCBA57///+3RscHDhzwRDIIq8n/cZmM1X3YACMhTyGrAwDx6CnAhMxQlwAAAABJRU5ErkJggg==");
    }

    static Drawable nine(Resources res, String k) { init(); return VolArt.nine(res, k); }
}
